params.command:
$ErrorActionPreference='Stop'
$dir=Join-Path $env:USERPROFILE 'actions-runner-heaven'
$workers=@(Get-CimInstance Win32_Process -ErrorAction Stop | Where-Object { $_.Name -eq 'Runner.Worker.exe' -and $_.ExecutablePath -and $_.ExecutablePath.StartsWith($dir,[System.StringComparison]::OrdinalIgnoreCase) })
$killed=@()
foreach($w in $workers){
  $parent=Get-CimInstance Win32_Process -Filter ("ProcessId="+$w.ParentProcessId) -ErrorAction SilentlyContinue
  if(-not $parent -or $parent.Name -ne 'Runner.Listener.exe'){ Stop-Process -Id $w.ProcessId -Force -ErrorAction Stop; $killed += $w.ProcessId }
}
Start-Sleep -Seconds 2
$listener=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'Runner.Listener.exe' -and $_.ExecutablePath -and $_.ExecutablePath.StartsWith($dir,[System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
if(-not $listener){
  $run=Join-Path $dir 'run.cmd'
  if(-not (Test-Path $run)){ throw ('missing runner entrypoint: '+$run) }
  $cmdExe=Join-Path ([Environment]::SystemDirectory) 'cmd.exe'
  Start-Process -FilePath $cmdExe -ArgumentList ('/d /c ""{0}""' -f $run) -WorkingDirectory $dir -WindowStyle Hidden | Out-Null
  Start-Sleep -Seconds 5
}
$final=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -in @('Runner.Listener.exe','Runner.Worker.exe') -and $_.ExecutablePath -and $_.ExecutablePath.StartsWith($dir,[System.StringComparison]::OrdinalIgnoreCase) } | Select-Object ProcessId,ParentProcessId,Name,ExecutablePath)
[pscustomobject]@{killed_orphan_workers=$killed; final=$final} | ConvertTo-Json -Depth 5
